window.DRILLS = {"L3": {"video": "drill_l3", "title": "The 70% Drill", "tag": "UNCERTAINTY", "nar": ["Time for the drill. This one tests how much certainty you need before you move.", "Press Play, and Melissa will stop to ask what you notice, then ask you to choose, then give you a second decision. Answer each time, and the video carries on."], "opts": ["Act with what you know", "Ask for the one missing input that matters most", "Push the decision to someone else", "Wait for more certainty"], "optsAt": [58.5, 61.1, 66.1, 68.9], "beats": [{"t": 3.2, "u": 16.4, "kind": "shift", "text": "Four pieces of new information arrive, one at a time. Then nothing more comes."}, {"t": 16.6, "u": 28.2, "kind": "shift", "text": "This is all the information you're going to get. The decision is due now."}, {"t": 44.7, "u": 56.4, "kind": "reframe", "text": "Everyone has a number: the certainty they need before they'll move. Most people never test theirs."}, {"t": 58.5, "u": 70.9, "kind": "options", "text": "Your options"}, {"t": 86.3, "u": 95.6, "kind": "again", "text": "New decision. The same amount of information: four pieces out of six."}, {"t": 106.6, "u": 123.8, "kind": "condition", "text": "This week, notice one decision where you're waiting for more certainty than you need, and move on what you have."}], "holds": [{"t": 28.2, "resume": 44.5, "key": "notice", "kind": "text", "label": "NOTICE", "q": "What do you notice right away? The pull to wait, the urge to move, something else?"}, {"t": 70.9, "resume": 86.1, "key": "choose", "kind": "choice", "label": "CHOOSE", "q": "The decision is due now. What do you do?"}, {"t": 95.6, "resume": 106.8, "key": "again", "kind": "choice", "label": "GO AGAIN", "q": "New decision, same information. What do you do this time?"}]}};
